import { Mesh, PlaneGeometry, RepeatWrapping, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string, depthMapUrl?:string, meshUrl?:string}} assets
 * @property {{position?:[number,number,number], rotation?:[number,number,number], scale?:[number,number,number]}} scenePlacement
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {{x:number,y:number,width:number,height:number}} atlasRegion
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {Record<string, Function>} primitives
 * @property {any} fontAtlas
 */

export default function createNode(config, ctx) {
  // ----- Geometry ------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1, 1, 1);

  // ----- Texture --------------------------------------------------------------
  const texture = ctx.textureLoader(config.assets.imageUrl);
  texture.wrapS = RepeatWrapping;
  texture.wrapT = RepeatWrapping;

  // Apply atlas UV region if specified
  const region = config.atlasRegion;
  if (region && texture.image) {
    const img = texture.image;
    const texW = img.width;
    const texH = img.height;

    const uOffset = region.x / texW;
    const vOffset = 1 - (region.y + region.height) / texH; // Flip Y because UV origin is bottom‑left
    const uRepeat = region.width / texW;
    const vRepeat = region.height / texH;

    texture.offset.set(uOffset, vOffset);
    texture.repeat.set(uRepeat, vRepeat);
    texture.needsUpdate = true;
  }

  // ----- Material -------------------------------------------------------------
  const material = new MeshBasicNodeMaterial({ map: texture });

  // ----- Mesh -----------------------------------------------------------------
  const plane = new Mesh(geometry, material);
  plane.name = config.name || 'collection-card-1';

  // ----- Placement ------------------------------------------------------------
  const pos = (config.scenePlacement?.position) || [0, 0, 0];
  const rot = (config.scenePlacement?.rotation) || [0, 0, 0];
  const scl = (config.scenePlacement?.scale) || [1, 1, 1];

  plane.position.set(pos[0], pos[1], pos[2]);
  plane.rotation.set(rot[0], rot[1], rot[2]);
  plane.scale.set(scl[0], scl[1], scl[2]);

  // ----- Cinematic primitives -------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(plane, primitive.params);
      }
    }
  }

  // ----- Event handlers placeholder -------------------------------------------
  plane.userData.handlers = {};

  // ----- GSAP timeline (empty, kept for cleanup) -------------------------------
  const timeline = gsap.timeline({ paused: true });

  // ----- Cleanup --------------------------------------------------------------
  plane.userData.cleanup = () => {
    // Stop any GSAP animations
    timeline.kill();

    // Dispose Three.js resources
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();

    // Remove from parent if still attached
    if (plane.parent) plane.parent.remove(plane);
  };

  return plane;
}
